function recordingFetch(
  response: FetchResponseLike | (() => FetchResponseLike | Promise<FetchResponseLike>),
): FetchLike & { calls: Array<{ url: string; init: FetchInit }> } {
  const calls: Array<{ url: string; init: FetchInit }> = [];
  const fn = async (url: string, init: FetchInit = {}): Promise<FetchResponseLike> => {
    calls.push({ url, init });
    return typeof response === "function" ? await response() : response;
  };
  return Object.assign(fn, { calls });
}

