export function makeClock(start = 1_000_000) {
  let t = start;
  const now = () => t;
  now.advance = (ms) => {
    t += ms;
  };
  return now;
}

function fakeClock(startMs: number): FakeClock {
  let t = startMs;
  const now = (() => t) as FakeClock;
  now.advance = (ms: number) => {
    t += ms;
  };
  now.set = (ms: number) => {
    t = ms;
  };
  return now;
}

