function renderOpenCodeGlobalPermissionConfig(existing?: unknown): Record<string, unknown> {
  const existingPermission = objectValue(existing);
  const merged: Record<string, unknown> = {
    ...existingPermission,
    read: "allow",
    glob: "allow",
