function parseLedger(text: string): TokenUsageEntry[] {
  const entries: TokenUsageEntry[] = [];
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      const parsed = JSON.parse(trimmed) as TokenUsageEntry;
      if (parsed && typeof parsed.packet_id === "string") entries.push(parsed);
    } catch {
      // Malformed line — skip it; scoring proceeds over the rest.
    }
  }
  return entries;
}

export function globMatches(filePath: string, glob: string): boolean {
  const f = normalize(filePath);
  const g = normalize(glob);
  if (!g.includes("*") && !g.includes("?")) {
    return pathMatchesPrefix(f, g);
  }
  // Translate the glob to a regex char-by-char so `*` / `**` / `?` are handled
  // and every other character is escaped — no placeholder substitution.
  let re = "";
  for (let i = 0; i < g.length; i++) {
    const c = g[i];
    if (c === "*") {
      if (g[i + 1] === "*") {
        re += ".*";
        i++;
      } else {
        re += "[^/]*";
      }
    } else if (c === "?") {
      re += "[^/]";
    } else if (/[.+^${}()|[\]\\]/.test(c)) {
      re += `\\${c}`;
    } else {
      re += c;
    }
  }
  return new RegExp(`^${re}$`).test(f);
}

