function visitImportDeclaration(
  state: AnalyzeState,
  imports: GraphEdge[],
  fromPath: string,
  node: TS.ImportDeclaration,
): void {
  if (!state.ts.isStringLiteral(node.moduleSpecifier)) return;
  const target = resolveSpecifierTarget(
    state,
    node.moduleSpecifier.text,
    node.getSourceFile().fileName,
  );
  if (target && target !== fromPath) {
    imports.push(
      graphEdge({
        from: fromPath,
        to: target,
        kind: "ts-import",
        confidence: TS_IMPORT_EDGE_CONFIDENCE,
        reason: `TypeScript resolved import '${node.moduleSpecifier.text}' to '${target}'.`,
      }),
    );
  }
}

function visitExportDeclaration(
  state: AnalyzeState,
  imports: GraphEdge[],
  fromPath: string,
  node: TS.ExportDeclaration,
): void {
  if (!node.moduleSpecifier || !state.ts.isStringLiteral(node.moduleSpecifier)) return;
  const target = resolveSpecifierTarget(
    state,
    node.moduleSpecifier.text,
    node.getSourceFile().fileName,
  );
  if (target && target !== fromPath) {
    imports.push(
      graphEdge({
        from: fromPath,
        to: target,
        kind: "ts-reexport",
        confidence: TS_REEXPORT_EDGE_CONFIDENCE,
        reason: `TypeScript resolved re-export '${node.moduleSpecifier.text}' to '${target}'.`,
      }),
    );
  }
}

function visitImportEqualsDeclaration(
  state: AnalyzeState,
  imports: GraphEdge[],
  fromPath: string,
  node: TS.ImportEqualsDeclaration,
): void {
  const ts = state.ts;
  if (
    !ts.isExternalModuleReference(node.moduleReference) ||
    !ts.isStringLiteral(node.moduleReference.expression)
  ) {
    return;
  }
  const target = resolveSpecifierTarget(
    state,
    node.moduleReference.expression.text,
    node.getSourceFile().fileName,
  );
  if (target && target !== fromPath) {
    imports.push(
      graphEdge({
        from: fromPath,
        to: target,
        kind: "ts-import",
        confidence: TS_IMPORT_EDGE_CONFIDENCE,
        reason: `TypeScript resolved import-equals to '${target}'.`,
      }),
    );
  }
}

export function sourceManifestsEquivalent(
  a: IntakeSourceManifest | undefined,
  b: IntakeSourceManifest | undefined,
): boolean {
  if (!a || !b) return false;
  if (a.sources.length !== b.sources.length) return false;
  return a.sources.every((source, index) => {
    const other = b.sources[index];
    return source.type === other.type && source.path === other.path;
  });
}

