function readAntigravityToken(env: NodeJS.ProcessEnv, stateDbPath: string): string | null {
  if (env.ANTIGRAVITY_ACCESS_TOKEN) return env.ANTIGRAVITY_ACCESS_TOKEN;
  try {
    const r = spawnSync(
      "sqlite3",
      [stateDbPath, "SELECT value FROM ItemTable WHERE key='antigravityAuthStatus'"],
      { encoding: "utf8", shell: false, windowsHide: true },
    );
    if (r.status !== 0 || !r.stdout) return null;
    const apiKey = (JSON.parse(r.stdout.trim()) as { apiKey?: string }).apiKey;
    return apiKey ?? null;
  } catch {
    return null;
  }
}

private readCredentials(): { accessToken: string; accountId: string } | null {
  let parsed: CodexCredentials;
  try {
    parsed = JSON.parse(readFileSync(this.credentialsPath, "utf8")) as CodexCredentials;
  } catch {
    return null;
  }
  const t = parsed.tokens;
  if (!t?.access_token || !t.account_id) return null;
  return { accessToken: t.access_token, accountId: t.account_id };
}

